import { useEffect, useState } from "react";

import "./Users.css";

function Users() {
  const [user, setUser] = useState([]);

  useEffect(() => {
    function getData() {
        let data = fetch("https://673b986796b8dcd5f3f6e23a.mockapi.io/dataForReact")
        .then((res) => res.json())
        .then((res) => setUser(res));

        console.log(data);

    }
    getData();
  }, []);

  return (
    <div>
      <p>
        {user.map((elm) => {
          return elm.name;
        })}
      </p>
    </div>
  );
}

export default Users;
